//! VMess tests: requests and responses of sing-vmess (Go vectors in
//! `testdata/vmess_vectors.json`, generated by `testdata/generate-vmess`)
//! read by rust-box, and rust-box clients and servers with each other.

use std::sync::atomic::{AtomicI64, Ordering};
use std::sync::Arc;

use rb_adapter::{BoxStream, PacketConn, Socksaddr};
use serde_json::Value;
use tokio::io::{AsyncReadExt, AsyncWriteExt};

use super::codec::{BodyKeys, BodyReader, Chunk};
use super::protocol::{self, COMMAND_MUX, COMMAND_TCP, COMMAND_UDP};
use super::session::{ClientConfig, ServerUsers};
use super::stream::{VmessPacketConn, VmessStream};
use crate::vless::protocol::parse_uuid;

const USER: &str = "bf000d23-0752-40b4-affe-68f7707a9661";

static VECTOR_TIME: AtomicI64 = AtomicI64::new(0);

fn vector_time() -> i64 {
    VECTOR_TIME.load(Ordering::SeqCst)
}

fn hex(text: &str) -> Vec<u8> {
    (0..text.len()).step_by(2).map(|index| u8::from_str_radix(&text[index..index + 2], 16).unwrap()).collect()
}

/// The client's reader of a response to a request the server read.
fn response_reader(keys: &BodyKeys, legacy: bool, response_header: u8) -> BodyReader {
    let (key, nonce) = protocol::response_keys(legacy, &keys.request_key, &keys.request_nonce);
    let keys = BodyKeys { key, nonce, ..*keys };
    if legacy {
        BodyReader::legacy_client(&keys, response_header)
    } else {
        BodyReader::aead_client(&keys)
    }
}

/// Every chunk `reader` gets out of `wire`.
fn chunks(mut reader: BodyReader, wire: &[u8]) -> Vec<Vec<u8>> {
    reader.raw_mut().extend_from_slice(wire);
    let mut chunks = Vec::new();
    while let Some(chunk) = reader.decode().unwrap() {
        match chunk {
            Chunk::Data(data) => chunks.push(data),
            Chunk::Eof => break,
        }
    }
    chunks
}

#[tokio::test]
async fn sing_vmess_vectors() {
    let vectors: Value = serde_json::from_str(include_str!("../../testdata/vmess_vectors.json")).unwrap();
    let uuid = parse_uuid(USER);
    for vector in vectors.as_array().unwrap() {
        let name = vector["name"].as_str().unwrap();
        VECTOR_TIME.store(vector["time"].as_i64().unwrap(), Ordering::SeqCst);
        let users = ServerUsers::with_time(&[(uuid, vector["alter_id"].as_i64().unwrap())], vector_time);
        let wire = hex(vector["request"].as_str().unwrap());
        let mut input: &[u8] = &wire;
        let request = users.read_request(&mut input).await.unwrap_or_else(|error| panic!("{name}: {error}"));
        assert_eq!(request.user, 0, "{name}");
        assert_eq!(request.legacy, vector["alter_id"].as_i64().unwrap() > 0, "{name}");
        assert_eq!(
            request.destination.as_ref().unwrap().to_string(),
            vector["destination"].as_str().unwrap(),
            "{name}"
        );
        let request_payload = hex(vector["request_payload"].as_str().unwrap());
        let response_payload = hex(vector["response_payload"].as_str().unwrap());
        let response_wire = hex(vector["response"].as_str().unwrap());
        let reader = response_reader(&request.keys, request.legacy, request.response_header);
        match vector["command"].as_str().unwrap() {
            "tcp" => {
                assert_eq!(request.command, COMMAND_TCP, "{name}");
                let mut stream = VmessStream::new(input, request.writer, request.reader);
                let mut received = Vec::new();
                stream.read_to_end(&mut received).await.unwrap_or_else(|error| panic!("{name}: {error}"));
                assert_eq!(received, request_payload, "{name}: request");
                assert_eq!(chunks(reader, &response_wire).concat(), response_payload, "{name}: response");
            }
            "udp" => {
                assert_eq!(request.command, COMMAND_UDP, "{name}");
                let packets = vector["packets"].as_u64().unwrap() as usize;
                let mut body = request.reader;
                body.raw_mut().extend_from_slice(input);
                let mut received = Vec::new();
                while let Some(Chunk::Data(data)) = body.decode().unwrap() {
                    received.push(data);
                }
                assert_eq!(received, vec![request_payload.clone(); packets], "{name}: request");
                assert_eq!(chunks(reader, &response_wire), vec![response_payload.clone(); packets], "{name}: response");
            }
            other => panic!("{other}"),
        }
        if !request.legacy {
            // The same auth id again (sing-vmess's replay filter).
            let mut again: &[u8] = &wire;
            let error = users.read_request(&mut again).await.err().unwrap();
            assert_eq!(error.to_string(), "replayed request", "{name}");
        }
    }
}

const SECURITIES: [&str; 6] = ["auto", "none", "zero", "aes-128-gcm", "chacha20-poly1305", "aes-128-cfb"];

/// A rust-box client and server: every security, option and header kind,
/// TCP (a write over several chunks) and UDP.
#[tokio::test]
async fn client_and_server() {
    let uuid = parse_uuid(USER);
    let large: Vec<u8> = (0..40_000u32).map(|index| (index * 13) as u8).collect();
    for security in SECURITIES {
        for alter_id in [0i64, 1] {
            for (padding, authenticated) in [(false, false), (true, false), (false, true), (true, true)] {
                let name = format!("{security} alter_id={alter_id} padding={padding} authenticated={authenticated}");
                let client = ClientConfig::new(
                    &uuid,
                    protocol::client_security(security).unwrap(),
                    alter_id,
                    padding,
                    authenticated,
                );
                let users = ServerUsers::new(&[(parse_uuid("other"), 0), (uuid, alter_id.max(0) * 3)]);
                let destination = Socksaddr::from_host_port("example.com", 443);

                // TCP over a pipe, both sides as streams.
                let (client_end, mut server_end) = tokio::io::duplex(1 << 20);
                let (writer, reader) = client.handshake(COMMAND_TCP, &destination).unwrap();
                let mut client_stream = VmessStream::new(client_end, writer, reader);
                client_stream.write_all(&large).await.unwrap();
                client_stream.flush().await.unwrap();
                let request =
                    users.read_request(&mut server_end).await.unwrap_or_else(|error| panic!("{name}: {error}"));
                assert_eq!((request.user, request.command), (1, COMMAND_TCP), "{name}");
                assert_eq!(request.destination.as_ref(), Some(&destination), "{name}");
                assert_eq!(request.legacy, alter_id > 0, "{name}");
                let mut server_stream = VmessStream::new(server_end, request.writer, request.reader);
                let mut received = vec![0u8; large.len()];
                server_stream.read_exact(&mut received).await.unwrap_or_else(|error| panic!("{name}: {error}"));
                assert_eq!(received, large, "{name}");
                server_stream.write_all(b"reply").await.unwrap();
                server_stream.write_all(&large[..20_000]).await.unwrap();
                server_stream.shutdown().await.unwrap();
                let mut reply = vec![0u8; 5 + 20_000];
                client_stream.read_exact(&mut reply).await.unwrap_or_else(|error| panic!("{name}: {error}"));
                assert_eq!(&reply[..5], b"reply", "{name}");
                assert_eq!(&reply[5..], &large[..20_000], "{name}");
                // The server's end closes: the client reads the end.
                drop(server_stream);
                let mut rest = Vec::new();
                client_stream.read_to_end(&mut rest).await.unwrap();
                assert!(rest.is_empty(), "{name}");

                // UDP: one chunk per packet.
                let (client_end, mut server_end) = tokio::io::duplex(1 << 20);
                let target = Socksaddr::from_host_port("1.2.3.4", 53);
                let (writer, reader) = client.handshake(COMMAND_UDP, &target).unwrap();
                let client_conn = VmessPacketConn::new(Box::new(client_end), writer, reader, target.clone());
                client_conn.write_packet(b"query one", &target).await.unwrap();
                client_conn.write_packet(b"query two", &target).await.unwrap();
                let request =
                    users.read_request(&mut server_end).await.unwrap_or_else(|error| panic!("{name}: {error}"));
                assert_eq!(request.command, COMMAND_UDP, "{name}");
                let server_conn = VmessPacketConn::new(
                    Box::new(server_end) as BoxStream,
                    request.writer,
                    request.reader,
                    target.clone(),
                );
                let mut buffer = [0u8; 2048];
                for expected in [&b"query one"[..], b"query two"] {
                    let (length, address) = server_conn.read_packet(&mut buffer).await.unwrap();
                    assert_eq!((&buffer[..length], &address), (expected, &target), "{name}");
                }
                server_conn.write_packet(b"answer", &target).await.unwrap();
                let (length, address) = client_conn.read_packet(&mut buffer).await.unwrap();
                assert_eq!((&buffer[..length], &address), (&b"answer"[..], &target), "{name}");
            }
        }
    }
}

/// A mux request carries XUDP frames to the shared mux server.
#[tokio::test]
async fn xudp_over_mux_request() {
    use crate::vless::mux::{self, MuxHandler};
    use crate::vless::packet::XudpPacketConn;

    struct Echo;

    #[async_trait::async_trait]
    impl MuxHandler for Echo {
        async fn new_connection(self: Arc<Self>, _destination: Socksaddr, _stream: BoxStream) {}

        async fn new_packet_connection(self: Arc<Self>, _destination: Socksaddr, conn: rb_adapter::SharedPacketConn) {
            let mut buffer = [0u8; 256];
            let (length, address) = conn.read_packet(&mut buffer).await.unwrap();
            conn.write_packet(&buffer[..length], &address).await.unwrap();
        }
    }

    let uuid = parse_uuid(USER);
    let client = ClientConfig::new(&uuid, protocol::client_security("aes-128-gcm").unwrap(), 0, true, false);
    let users = Arc::new(ServerUsers::new(&[(uuid, 0)]));
    let (client_end, mut server_end) = tokio::io::duplex(65536);
    let target = Socksaddr::from_host_port("8.8.8.8", 53);
    let (writer, reader) = client.handshake(COMMAND_MUX, &target).unwrap();
    let stream: BoxStream = Box::new(VmessStream::new(client_end, writer, reader));
    let conn = XudpPacketConn::new(stream, target.clone());
    conn.write_packet(b"ping", &target).await.unwrap();
    let request = users.read_request(&mut server_end).await.unwrap();
    assert_eq!(request.command, COMMAND_MUX);
    assert_eq!(request.destination, None);
    let server: BoxStream = Box::new(VmessStream::new(server_end, request.writer, request.reader));
    tokio::spawn(mux::serve(server, Arc::new(Echo)));
    let mut buffer = [0u8; 64];
    let (length, address) = conn.read_packet(&mut buffer).await.unwrap();
    assert_eq!((&buffer[..length], address), (&b"ping"[..], target));
}

#[tokio::test]
async fn request_errors() {
    let uuid = parse_uuid(USER);
    let users = ServerUsers::new(&[(uuid, 0)]);
    // Shorter than an AEAD request.
    let mut short: &[u8] = &[0u8; 50];
    assert_eq!(users.read_request(&mut short).await.err().unwrap().to_string(), "bad header");
    // An unknown user.
    let stranger = ClientConfig::new(&parse_uuid("stranger"), protocol::SECURITY_NONE, 0, false, false);
    let (writer, _) = stranger.handshake(COMMAND_TCP, &Socksaddr::from_host_port("1.1.1.1", 80)).unwrap();
    let mut writer = writer;
    let wire = writer.encode(b"x");
    let mut input: &[u8] = &wire;
    assert_eq!(users.read_request(&mut input).await.err().unwrap().to_string(), "bad request");
    // A request from too far in the past.
    static OLD: AtomicI64 = AtomicI64::new(0);
    OLD.store(super::session::unix_now() + 200, Ordering::SeqCst);
    let late = ServerUsers::with_time(&[(uuid, 0)], || OLD.load(Ordering::SeqCst));
    let client = ClientConfig::new(&uuid, protocol::SECURITY_NONE, 0, false, false);
    let (mut writer, _) = client.handshake(COMMAND_TCP, &Socksaddr::from_host_port("1.1.1.1", 80)).unwrap();
    let wire = writer.encode(b"x");
    let mut input: &[u8] = &wire;
    assert_eq!(late.read_request(&mut input).await.err().unwrap().to_string(), "bad timestamp");
    // A legacy request outside the keys' window is unknown.
    let legacy_users = ServerUsers::with_time(&[(uuid, 2)], || OLD.load(Ordering::SeqCst) + 1000);
    let legacy = ClientConfig::new(&uuid, protocol::SECURITY_NONE, 1, false, false);
    let (mut writer, _) = legacy.handshake(COMMAND_TCP, &Socksaddr::from_host_port("1.1.1.1", 80)).unwrap();
    let wire = writer.encode(b"x");
    let mut input: &[u8] = &wire;
    assert_eq!(legacy_users.read_request(&mut input).await.err().unwrap().to_string(), "bad request");
}

#[test]
fn chunk_errors() {
    let keys = BodyKeys {
        security: protocol::SECURITY_LEGACY,
        option: protocol::OPTION_CHUNK_STREAM,
        request_key: [1; 16],
        request_nonce: [2; 16],
        key: [1; 16],
        nonce: [2; 16],
    };
    // A legacy chunk whose checksum does not match.
    let mut reader = BodyReader::new(&keys, None, vec![0, 6, 0, 0, 0, 0, b'h', b'i']);
    assert_eq!(reader.decode().unwrap_err().to_string(), "vmess: invalid chunk checksum");
    // A chunk of no data is the end.
    let keys = BodyKeys { security: protocol::SECURITY_NONE, option: protocol::OPTION_CHUNK_STREAM, ..keys };
    let mut reader = BodyReader::new(&keys, None, vec![0, 0]);
    assert_eq!(reader.decode().unwrap(), Some(Chunk::Eof));
    // Padding longer than the chunk.
    let keys = BodyKeys { option: protocol::OPTION_CHUNK_STREAM | protocol::OPTION_GLOBAL_PADDING, ..keys };
    let mut probe = super::codec::Shake::new(&keys.nonce);
    let padding = probe.next_u16() % 64;
    if padding > 1 {
        let mut reader = BodyReader::new(&keys, None, vec![0, 1]);
        assert_eq!(reader.decode().unwrap_err().to_string(), format!("bad length chunk: length=1, padding={padding}"));
    }
}
